function startKillcam(enemy,head,from){const dir=head.clone().sub(from);const dist=dir.length();dir.normalize();const cam=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.05,camera.far);
 const bullet=new THREE.Group();const core=new THREE.Mesh(new THREE.CylinderGeometry(.012,.012,.07,8),new THREE.MeshStandardMaterial({color:0xc8a060,metalness:.9,roughness:.25,emissive:0x553311}));core.rotation.x=Math.PI/2;bullet.add(core);
 const trail=new THREE.Mesh(new THREE.CylinderGeometry(.004,.03,2.2,8,1,true),new THREE.MeshBasicMaterial({color:0xfff0c8,transparent:true,opacity:.35,blending:THREE.AdditiveBlending,depthWrite:false}));trail.rotation.x=Math.PI/2;trail.position.z=-1.15;bullet.add(trail);scene.add(bullet);
 const side=new THREE.Vector3(-dir.z,0,dir.x).normalize();if(Math.random()<.5)side.negate();
 killcam={t:0,dur:dist>6?2.6:2.0,bulletT:dist>6?.32:.18,enemy,head,from,dir,dist,cam,bullet,side,scale:.14};killcamCooldown=9;slowmo=0;
 document.body.classList.add('killcam');audio.whoosh?.();audio.muffle(2,700);music.cue('slowmo');audio.tone?.(48,.9,.35,'sine',30,{delay:.05});}
function updateKillcam(dt){const k=killcam;k.t+=dt;const u=k.t/k.dur;const e=k.enemy;
 const center=(e.ragdoll?.active&&e.ragdoll.center)?e.ragdoll.center.clone():e.root.position.clone().add(new THREE.Vector3(0,1,0));
 if(u<k.bulletT){const b=Math.min(1,u/k.bulletT),p=k.from.clone().addScaledVector(k.dir,k.dist*Math.pow(b,.85));k.bullet.visible=true;k.bullet.position.copy(p);k.bullet.lookAt(p.clone().add(k.dir));
  k.cam.position.copy(p).addScaledVector(k.dir,-.55).addScaledVector(k.side,.16).add(new THREE.Vector3(0,.05,0));k.cam.lookAt(p.clone().addScaledVector(k.dir,1.5));k.cam.fov=40;k.scale=.06;}
 else{k.bullet.visible=false;const v=(u-k.bulletT)/(1-k.bulletT),a=v*1.25;const base=k.side.clone().multiplyScalar(2.4).addScaledVector(k.dir,-1.2);const rot=base.applyAxisAngle(new THREE.Vector3(0,1,0),a-.4);
  k.cam.position.copy(center).add(rot).add(new THREE.Vector3(0,.55+v*.4,0));k.cam.lookAt(center.clone().add(new THREE.Vector3(0,.1,0)));k.cam.fov=46-v*6;k.scale=.16+v*.12;
  const floor=(forest?forest.heightAt(k.cam.position.x,k.cam.position.z):0)+.3;if(k.cam.position.y<floor)k.cam.position.y=floor;}
 k.cam.aspect=innerWidth/innerHeight;k.cam.updateProjectionMatrix();
 if(k.t>=k.dur||!playing){scene.remove(k.bullet);killcam=null;document.body.classList.remove('killcam');audio.muffle(.2,4000);}}
// ---------- Online multiplayer ----------
function onlineRoom(){return (new URLSearchParams(location.search).get('room')||profile.data.settings.room||'public').toLowerCase().replace(/[^a-z0-9_-]/g,'').slice(0,20)||'public';}
async function joinOnline(){const url=new URLSearchParams(location.search).get('server')||profile.data.settings.server||defaultServer();net=new NetClient(url);
 try{await net.connect();}catch(err){$('#status').innerHTML=`Could not reach the online server (${url}).<br>Start it with START_ONLINE_SERVER (or <code>node server/server.mjs</code>) and open the address it prints. <a href="?mode=tdm">Play offline with bots instead</a>.`;$('#play').textContent='OFFLINE';throw err;}
 return new Promise((resolve,reject)=>{net.on('welcome',m=>resolve(m));net.on('full',()=>{$('#status').textContent='Room is full (10 players). Pick another room in the lobby.';reject(new Error('Room full'));});net.send({t:'join',name:profile.data.name,room:onlineRoom()});});}
function setupOnline(w){const B=enemies;B.myId=w.id;B.player.team=w.team;B.player.netId=w.id;mission.elapsed=w.elapsed;mission.score={...w.score};for(const p of w.players)if(p.id!==w.id)B.addRemote(p);
 const ke=mission.killEvent.bind(mission);mission.killEvent=(k,v,wpn,h)=>{if(v.isPlayer&&!fromNet){const d=v.isPlayer&&k?.root?camera.position.clone().sub(k.root.position).normalize():null;net.send({t:'died',by:k?.netId??w.id,w:wpn,head:!!h,dir:d?[+d.x.toFixed(2),+d.y.toFixed(2),+d.z.toFixed(2)]:null});}ke(k,v,wpn,h);};
 const gt=grenades.throw.bind(grenades);grenades.throw=(from,dir,owner,power)=>{if(owner?.isPlayer&&!fromNet)net.send({t:'nade',a:from.toArray(),d:dir.toArray(),p:power||null});return gt(from,dir,owner,power);};
 if(grenades.explodeAt){const ex=grenades.explodeAt.bind(grenades);grenades.explodeAt=(pos,owner,wpn)=>{if(owner?.isPlayer&&!fromNet&&wpn==='airstrike')net.send({t:'boom',a:pos.toArray(),w:wpn});return ex(pos,owner,wpn);};}
 const V3=a=>new THREE.Vector3(a[0],a[1],a[2]);
 net.on('join',m=>{B.addRemote(m.player);chatLine('',`${m.player.name} joined the ${m.player.team.toUpperCase()} team`,'sys');audio.ui?.();})
  .on('leave',m=>{const e=B.byId.get(m.id);if(e)chatLine('',`${e.name} left the match`,'sys');B.removeRemote(m.id);})
  .on('snap',m=>{for(const [id,st] of m.s){if(id===w.id)continue;const e=B.byId.get(id);if(e)B.applyState(e,st);}})
  .on('shot',m=>{const e=B.byId.get(m.id);if(!e)return;const a=V3(m.a),b=V3(m.b);e.fired=.4;audio.shot(m.w,a.distanceTo(camera.position),panOf(a));effects.muzzle(a);effects.tracer(a.clone().add(new THREE.Vector3(0,-.1,0)),b,e.team!==B.player.team);const seg=b.clone().sub(a),l=seg.length(),t=Math.max(0,Math.min(1,camera.position.clone().sub(a).dot(seg)/(l*l)));if(a.clone().addScaledVector(seg,t).distanceTo(camera.position)<1.6&&t>.05&&t<.98){audio.whiz(panOf(a));combatTimer=8;}})
  .on('hit',m=>{const by=B.actor(m.by);if(!by||mission.playerDown)return;mission.hurt(m.dmg,by,m.head,by.root?.position,m.w);})
  .on('kill',m=>{mission.score={...m.score};if(m.victim===w.id)return;const k=B.actor(m.killer),v=B.byId.get(m.victim);if(!v)return;B.remoteKilled(v,m.dir,m.head);effects.bloodPool(v.root.position.clone());voices.death(v,{head:m.head},null);fromNet=true;try{ke(k||v,v,m.w,m.head);}finally{fromNet=false;}mission.score={...m.score};})
  .on('nade',m=>{const e=B.byId.get(m.id);if(!e)return;fromNet=true;try{grenades.throw(V3(m.a),V3(m.d),e,m.p||undefined);}finally{fromNet=false;}})
  .on('boom',m=>{const e=B.byId.get(m.id);if(!e||!grenades.explodeAt)return;fromNet=true;try{grenades.explodeAt(V3(m.a),e,m.w||'airstrike');}finally{fromNet=false;}})
  .on('clock',m=>{if(Math.abs(mission.elapsed-m.elapsed)>1.5)mission.elapsed=m.elapsed;mission.score={...m.score};for(const [id,ping] of m.pings){const a=B.actor(id);if(a)a.ping=ping;}})
  .on('end',m=>{mission.score={...m.score};mission.end();chatLine('',`Match over — ${m.winner==='draw'?'draw':m.winner.toUpperCase()+' team wins'}. Next match in a few seconds…`,'sys');})
  .on('restart',()=>{chatLine('','New match starting…','sys');setTimeout(()=>location.reload(),900);})
  .on('chat',m=>{chatLine(m.name,m.text,m.team);const e=B.byId.get(m.id);if(e&&m.emo)voices.enemy(e,m.emo,true);else if(e)voices.bubble(e.root,m.text,m.team==='red'?'#ff9a8a':'#9ac8ff','chat');})
  .on('close',()=>{chatLine('','Disconnected from the server.','sys');flash('CONNECTION LOST');});
 $('#hdrEyebrow').textContent='ONLINE TEAM DEATHMATCH · ROOM '+w.room.toUpperCase();$('#chatBox').hidden=false;chatLine('',`Online room “${w.room}” · you are on ${w.team.toUpperCase()} · Enter / Y to chat`,'sys');}
const QUICK=[['Nice shot!','happy'],['Follow me!','alert'],['Need backup!','fear'],['Enemy spotted!','alert'],['You will pay for that!','angry'],['GG!','happy'],['Noooo…','sad']];
function chatLine(name,text,team){const log=$('#chatLog');if(!log)return;const li=document.createElement('li');li.className=team==='sys'?'sys':'';li.innerHTML=(name?`<b class="${team}">${String(name).replace(/[<>&]/g,'')}</b> `:'')+String(text).replace(/[<>&]/g,'');log.append(li);while(log.children.length>7)log.firstChild.remove();setTimeout(()=>li.classList.add('old'),9000);}
function openChat(){const box=$('#chatBox'),inp=$('#chatInput');box.classList.add('open');$('#quickChat').innerHTML=QUICK.map(([t,e],i)=>`<button data-q="${i}">${i+1}. ${t}</button>`).join('');document.exitPointerLock?.();inp.value='';setTimeout(()=>inp.focus(),0);}
function closeChat(){$('#chatBox').classList.remove('open');$('#chatInput').blur();if(playing&&!mobile)canvas.requestPointerLock?.()?.catch?.(()=>{});}
function sendChat(text,emo=null){text=String(text||'').trim();if(!text||!net)return;net.send({t:'chat',text,emo});if(emo)voices.player(emo==='happy'?'happy':emo==='angry'?'angry':emo==='sad'?'cry':'spotted',true);}
$('#chatInput')?.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter'){sendChat(e.target.value);closeChat();}else if(e.key==='Escape'){closeChat();}else if(/^[1-7]$/.test(e.key)&&!e.target.value){e.preventDefault();const q=QUICK[+e.key-1];sendChat(q[0],q[1]);closeChat();}});
$('#quickChat')?.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const q=QUICK[+b.dataset.q];sendChat(q[0],q[1]);closeChat();});
$('#chatBtn')?.addEventListener('click',()=>{if(online)openChat();});
// Player emotions: polls mission state and voices lines / sets the portrait expression; drives the blood-on-screen overlay.
function reactions(dt){const tdm=mode==='tdm',hp=mission.health,dead=tdm?mission.playerDown:mission.dead;voices.muted=!playing||!!forest?.cinematic;voices.update(dt,hp);
 const kills=tdm?(enemies.player?.kills??0):mission.kills;if(kills>react.kills){voices.player(react.headKill?'headshot':'kill',react.headKill);react.headKill=false;}react.kills=kills;
 if(!tdm&&hp<react.health-.5&&enemies.lastAttacker){campHits.push({pos:enemies.lastAttacker.clone(),t:1.4});enemies.lastAttacker=null;}for(const h of campHits)h.t-=dt;campHits=campHits.filter(h=>h.t>0);if(!tdm)$('#hitdir').innerHTML=campHits.map(h=>{const d=h.pos.clone().sub(player.end);const rel=Math.atan2(d.x,d.z)-(yaw+Math.PI);return `<i style="transform:rotate(${(-rel*180/Math.PI).toFixed(1)}deg);opacity:${Math.min(1,h.t).toFixed(2)}"></i>`;}).join('');
 if(hp<react.health-.5&&!dead){const d=react.health-hp;voices.player(hp<30?'low':d>12||Math.random()<.4?'angry':'pain');if(hp<30)react.low=1;}else if(hp>react.health+8&&!react.dead){voices.player('heal');}react.health=hp;
 if(!tdm&&mission.alarm&&!react.alarm)voices.player('alarm');react.alarm=!!mission.alarm;
 if(forest&&mission.index!==react.objective){if(react.objective>=0)voices.player('happy');react.objective=mission.index;}
 if(dead&&!react.dead){voices.player('cry',true);voices.setFace('cry',tdm?4:99);if(!tdm)voices.playerDown(enemies,camera.position);}if(!dead&&react.dead&&tdm)voices.setFace('calm',.1);react.dead=dead;
 if(mission.won&&!react.won)voices.player('victory',true);react.won=mission.won;
 const blood=Math.min(.55,Math.max(mission.damageFlash*.6,hp<40?(40-hp)/40*.5:0,dead?.9:0));const bs=$('#bloodScreen');if(bs){bs.style.opacity=blood.toFixed(2);bs.classList.toggle('pulse',hp<30&&!dead);}}
let mapTick=0;function musicState(){if(!loaded)return 'menu';if(finished)return music.state;if(!playing)return music.state==='silent'?'menu':music.state;if(forest?.cinematic)return 'cinematic';if(mode==='tdm'){if(mission.damageFlash>0)combatTimer=8;return combatTimer>0?'combat':'tension';}if(mission.alarm||mission.damageFlash>0)combatTimer=Math.max(combatTimer,mission.alarm?3:8);if(combatTimer>0)return 'combat';return enemies.detected>.3?'tension':'stealth';}
function frame(){requestAnimationFrame(frame);const rawDt=clock.getDelta(),realDt=Math.min(rawDt,.05);fpsMeter.tick(rawDt,!!settings.fps);killcamCooldown=Math.max(0,killcamCooldown-realDt);if(killcam)updateKillcam(Math.min(rawDt,.25));slowCooldown=Math.max(0,slowCooldown-realDt);combatTimer=Math.max(0,combatTimer-realDt);if(killcam){timeScale+=(killcam.scale-timeScale)*Math.min(1,realDt*18);}else if(wheel.open&&!online){timeScale+=(.3-timeScale)*Math.min(1,realDt*10);}else if(slowmo>0){slowmo-=realDt;timeScale+=(.28-timeScale)*Math.min(1,realDt*14);}else timeScale+=(1-timeScale)*Math.min(1,realDt*4);const dt=realDt*timeScale;time+=dt;if(music.started&&(time*4|0)%2===0)music.setState(musicState());if(loaded){if(playing){const sdt=forest?.cinematic?Math.min(rawDt,.2)*timeScale:dt;if(yard&&yard.introT>0)yard.introStep(Math.min(rawDt,.1));else for(let i=0;i<5;i++)simulate(sdt/5);if(mode==='tdm')tdmHud(dt);if(forest&&!forest.cinematic){forest.hud(dt,yaw);$('#scope').hidden=!scoped;document.body.classList.toggle('scoped',scoped);}}else if(!finished){if(forest&&!forest.started){const t=time*.04;camera.position.set(Math.sin(t)*150,70,Math.cos(t)*150);camera.lookAt(0,4,0);forest.world.update(dt,camera.position);}else if(forest){}else if(mode==='tdm'){camera.position.set(6,48,52);camera.lookAt(6,0,-20)}else{camera.position.set(75,65,115);camera.lookAt(0,0,0)}}if(time-mapTick>.1){drawMap();if(playing&&!forest?.cinematic){const h=octree.rayIntersect(new THREE.Ray(camera.position.clone(),new THREE.Vector3(0,1,0)));audio.setIndoor(!!h&&h.distance<7.5);}if(playing&&mode!=='tdm'){doorTarget=doors.target(camera,world);const target=mission.nearby(camera);const body=target?null:lootTarget();$('#doorPrompt').textContent=forest?.prompt?forest.prompt:body?'E / USE — SEARCH BODY':target?'E / USE — '+(target.prompt||(target.type==='panel'?'DISABLE ALARM':target.type==='intel'?'RECOVER INTEL':'PICK UP '+target.type.toUpperCase())):doorTarget?'E / USE — '+(Math.abs(doorTarget.target)>.1?'CLOSE DOOR':'OPEN DOOR'):'';}mapTick=time;}}{const on=flashOn&&playing&&!killcam;torch.intensity=on?650:0;if(on){camera.updateMatrixWorld();const d=camera.getWorldDirection(new THREE.Vector3());torch.position.copy(camera.position).add(new THREE.Vector3(0,-.15,0)).addScaledVector(d,.3);torch.target.position.copy(camera.position).addScaledVector(d,12);torch.target.updateMatrixWorld();}}post.adapt(realDt);post.begin();if(!post.enabled)renderer.clear();renderer.render(scene,killcam?killcam.cam:camera);if(loaded&&playing&&!scoped&&!mission?.playerDown&&!(forest?.binoc)&&!killcam){renderer.clearDepth();renderer.render(weaponScene,weaponCamera)}post.end(realDt,{slow:slowmo>0||killcam?1:Math.max(0,1-timeScale)*.5,red:mission&&!mission.playerDown&&mission.health<25?(25-mission.health)/25*.22:0,cinema:forest?.cinematic?1:0,exposure:renderer.toneMappingExposure});}
window.addEventListener('resize',()=>{post.resize();camera.aspect=weaponCamera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();weaponCamera.updateProjectionMatrix()});
// Entry: ?mode=tdm or ?mode=campaign loads straight in (used by Play Again); otherwise show the lobby.
// Web app: service worker (offline + install), install prompt, fullscreen/landscape on phones.
if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol)&&!navigator.webdriver)navigator.serviceWorker.register('./sw.js').catch(()=>{});
let installEvt=null;addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvt=e;const b=$('#installBtn');if(b)b.hidden=false;});
$('#installBtn')?.addEventListener('click',async()=>{if(!installEvt)return;installEvt.prompt();try{await installEvt.userChoice;}catch(_){}installEvt=null;$('#installBtn').hidden=true;});
addEventListener('appinstalled',()=>{const b=$('#installBtn');if(b)b.hidden=true;});
async function immersive(){if(!mobile)return;try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen({navigationUI:'hide'});}catch(_){}try{await screen.orientation?.lock?.('landscape');}catch(_){}}
const requested=new URLSearchParams(location.search).get('mode');
const mParam=+new URLSearchParams(location.search).get('m')||1;if(requested==='yard'){const u=new URLSearchParams(location.search),mc=u.get('map')||'dust';load(`yard:${u.get('side')||'ct'}:${mc==='random'?(Math.random()<.5?'dust':'snow'):mc}:${u.get('dm')||'tdm'}:${mc}`);}else if(requested==='forest')load('forest:'+mParam);else if(requested==='tdm'&&new URLSearchParams(location.search).get('online'))load('online');else if(requested==='tdm'||requested==='campaign')load(requested);else{document.body.dataset.mode='lobby';initLobby(profile,audio,m=>load(m));}
